(function(){
  CardSpoke_MODS.register('starter-aesthetic-kit', {
    meta: {
      name: 'Starter Aesthetic Kit',
      type: 'Kit',
      version: '1.0.0',
      creator: 'CardSpoke Team',
      description: 'Pairs a clean serif typography touch with balanced spacing presets',
      releaseDate: '2024-10-20',
      source: 'official'
    },
    onAppInit(){
      document.documentElement.style.setProperty('--radius-lg', '18px');
      document.documentElement.style.setProperty('--text-family', '"DM Serif Display", Georgia, serif');
    },
    onDisable(){
      document.documentElement.style.removeProperty('--radius-lg');
      document.documentElement.style.removeProperty('--text-family');
    }
  });
})();
